".sim-form-container h3 {
  font-size: 14px;
  font-weight: 800;
  margin-bottom: 16px;
  color: var(--primary-navy);
}

/* Simulator add-on section label separator */
.sim-addon-section-label {
  font-size: 10.5px;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.6px;
  color: var(--text-muted);
  border-top: 1px dashed var(--border-color);
  border-bottom: 1px dashed var(--border-color);
  padding: 7px 0;
  margin: 14px 0 10px 0;
}

/* Add-on checklist group */
.addon-checklist {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-bottom: 4px;
}

.addon-check-item {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  padding: 8px 10px;
  border: 1px solid var(--border-color);
  border-radius: var(--border-radius-sm);
  cursor: pointer;
  transition: all var(--transition-fast);
  background-color: var(--bg-light);
}

.addon-check-item:hover {
  border-color: var(--primary-blue);
  background-color: var(--primary-blue-light);
}

.addon-check-item input[type="checkbox"] {
  margin-top: 2px;
  width: 14px;
  height: 14px;
  accent-color: var(--primary-blue);
  cursor: pointer;
  flex-shrink: 0;
}

.addon-check-text {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.addon-check-text span {
  font-size: 12px;
  font-weight: 700;
  color: var(--text-dark);
}

.addon-check-text small {
  font-size: 10px;
  color: var(--text-muted);
}

/* Breakdown divider line */
.breakdown-divider {
  border-top: 1px solid rgba(255, 255, 255, 0.07);
  margin: 2px 0;
}"

